package com.circlenet.domain.privacy;
import com.circlenet.domain.profile.UserProfileRepository; import com.circlenet.domain.user.*; import com.circlenet.domain.user.model.UserEntity; import java.time.Instant; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class PrivacyService {private final UserBlockRepository blocks;private final UserRepository users;private final UserProfileRepository profiles;public PrivacyService(UserBlockRepository b,UserRepository u,UserProfileRepository p){blocks=b;users=u;profiles=p;}public record BlockedUser(Long userId,String displayName,String profilePhoto,Instant blockedAt){} public List<BlockedUser> list(Long userId){return blocks.findByBlockerUserIdOrderByCreatedAtDesc(userId).stream().map(this::dto).toList();}public BlockedUser block(Long userId,Long targetId){if(targetId==null||userId.equals(targetId))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose another account");users.findById(targetId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Account not found"));var entity=blocks.findByBlockerUserIdAndBlockedUserId(userId,targetId).orElseGet(()->{var b=new UserBlockEntity();b.setBlockerUserId(userId);b.setBlockedUserId(targetId);return blocks.save(b);});return dto(entity);}public void unblock(Long userId,Long targetId){blocks.findByBlockerUserIdAndBlockedUserId(userId,targetId).ifPresent(blocks::delete);}private BlockedUser dto(UserBlockEntity b){UserEntity u=users.findById(b.getBlockedUserId()).orElseThrow();String n=((u.getFirstName()==null?"":u.getFirstName())+" "+(u.getSurname()==null?"":u.getSurname())).trim();if(n.isBlank())n=u.getUsername();return new BlockedUser(u.getId(),n,profiles.findById(u.getId()).map(x->x.getProfilePhoto()).orElse(null),b.getCreatedAt());}}
